{
  "technical_and_design_decisions": [
    "Implement U1 in the Java contract API by making a transaction-scoped context available to contract methods, preserving existing contract invocation behavior where practical and avoiding shared mutable context between transactions.",
    "Treat U2 and U3 as duplicate statements of the same package-reorganization requirement; move utility code from protos/utils to protoutils and update generated-code imports, consumers, tests, and build configuration.",
    "Backport the existing Kafka broker health-check behavior to the Fabric 1.4 maintenance line, adapting it to the APIs and configuration conventions available in that release.",
    "For U5, introduce an explicit read-only chaincode invocation path for channel Readers rather than attempting to infer authorization from arbitrary chaincode execution. The read-only path will reject ledger writes while retaining the existing Writer authorization requirement for normal invocation.",
    "For U6, add a peer configuration option for the externally advertised Service Discovery endpoint and use that value in discovery responses, with the existing gossip external endpoint behavior retained as a fallback.",
    "For U7, expose the running peer or orderer version through the authenticated and TLS-protected operations service, using a small stable response schema suitable for operator tooling.",
    "For U8, update the relevant Go samples toward idiomatic Go structure, naming, error handling, and resource management without changing their intended functional behavior.",
    "Use existing Fabric coding conventions, protobuf generation tooling, configuration mechanisms, and test frameworks wherever possible to minimize compatibility risk."
  ],
  "assumptions": [
    "U2 and U3 are duplicates and require one implementation rather than two separate features.",
    "The increment is implemented against an existing Fabric 1.4-era codebase with established build, test, protobuf-generation, gossip, discovery, operations-service, and Kafka abstractions.",
    "The effort includes implementation, focused unit tests, relevant integration or component tests, documentation/configuration updates, and local validation, but excludes multi-organization acceptance testing and production deployment.",
    "No major protobuf wire-format redesign is required; any new externally visible messages or fields can be added compatibly.",
    "Backward compatibility is required for existing peer, orderer, chaincode, SDK, and configuration behavior unless a requirement explicitly introduces a new opt-in behavior.",
    "The read-only invocation design can be enforced at the supported chaincode invocation boundary and does not require proving that arbitrary chaincode code never performs indirect writes outside the normal ledger transaction.",
    "The Kafka health-check implementation and the operations-service version implementation can be adapted from patterns or code already available in the main development line.",
    "Sample updates are limited to the samples directly affected by the requested language-expression cleanup; a complete rewrite of all Fabric samples is out of scope.",
    "A workday represents one developer day of focused effort; elapsed calendar time, external review queues, and parallel staffing are not included."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment analysis and implementation planning",
      "activity_description": "Trace the affected Fabric modules, APIs, protobuf packages, configuration paths, authorization checks, discovery responses, operations service, Kafka health checks, and samples; define compatibility boundaries and a test plan.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement transaction context access for Java contracts",
      "activity_description": "Add the transaction-scoped context lifecycle and API exposure needed by Java contract methods, connect it to stub and transaction APIs, address thread-safety and object ownership, update relevant documentation, and add unit and contract-level tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "Move proto utilities to protoutils",
      "activity_description": "Relocate protos/utils implementation and generated or extension dependencies to the new package location, update imports and build generation rules, preserve externally consumable protobuf artifacts, and verify compatibility through package and compilation tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Backport Kafka health checks to Fabric 1.4",
      "activity_description": "Port Kafka broker health-check behavior and supporting configuration or status handling to the 1.4 codebase, adapt version-specific interfaces, cover healthy, unhealthy, unavailable, and recovery cases, and update operational documentation.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A5",
      "activity_name": "Enable channel Reader access to read-only chaincode invocation",
      "activity_description": "Design and implement the explicit read-only invocation path, enforce rejection of ledger mutations, integrate channel authorization for Readers, preserve normal Writer-controlled invocation, update protocol/API behavior as needed, and add authorization, read, write-rejection, and regression tests.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A6",
      "activity_name": "Configure peer external endpoint for Service Discovery",
      "activity_description": "Add the peer configuration option, propagate the explicitly configured endpoint into discovery advertisements, define fallback and validation behavior, update configuration documentation, and test Docker-style externally advertised addresses and legacy configurations.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Expose peer and orderer versions through the operations service",
      "activity_description": "Add authenticated operations-service version handlers and response structures for peers and orderers, connect them to the build/runtime version source, update service definitions and generated artifacts if required, and test TLS, authorization, and response behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Modernize affected Go samples",
      "activity_description": "Identify the samples covered by the requirement and revise them to use idiomatic Go naming, control flow, error handling, interfaces, and resource cleanup while preserving their instructional intent; run sample builds and applicable tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A9",
      "activity_name": "Cross-feature integration and regression validation",
      "activity_description": "Run targeted and broader Fabric test suites, validate protobuf consumers and generated code, exercise peer/orderer startup and configuration combinations, test discovery and operations clients, investigate and fix integration regressions, and verify backward compatibility.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation, release notes, and final packaging",
      "activity_description": "Document new APIs, configuration options, authorization behavior, operations endpoints, migration implications of the package move, and sample changes; update release notes and perform final build, lint, formatting, and artifact checks.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 75
  }
}

